#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
"""Generate bounded typed syntax copying and a separate structural consumer."""
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
NAMES = '''FunctionDeclarationSyntax ParameterSyntax BlockStatementSyntax ReturnStatementSyntax LocalDeclarationSyntax InferredLocalDeclarationSyntax StructLocalDeclarationSyntax StructDeclarationSyntax StructFieldDeclarationSyntax StructInitializerSyntax FieldInitializerSyntax TypeNameSyntax GenericTypeApplicationSyntax SliceTypeSyntax PointerTypeSyntax ArrayTypeSyntax NonNullTypeSyntax CallableChannelTypeSyntax CallExpressionSyntax NameExpressionSyntax IntegerLiteralExpressionSyntax FloatLiteralExpressionSyntax BooleanLiteralExpressionSyntax BinaryExpressionSyntax ShortCircuitExpressionSyntax PrefixExpressionSyntax ParenthesizedExpressionSyntax ConversionExpressionSyntax IfStatementSyntax WhileStatementSyntax ForStatementSyntax AssignmentStatementSyntax FieldAssignmentStatementSyntax CallStatementSyntax MoveExpressionSyntax BufferAllocationSyntax FieldAccessExpressionSyntax BreakStatementSyntax ContinueStatementSyntax WhereClauseSyntax HeapObjectConstructionSyntax ClassDeclarationSyntax LifecycleDeclarationSyntax'''.split()


def generate():
	model = json.loads((ROOT/'compiler/syntax/model.json').read_text())['nodes']
	copy = ['// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception', '// Generated by generate-specialization.py; typed AST edges, original tokens/spans.', 'SyntaxNodeId generic_copy_node(CheckedIndex index, GenericInstance plan, SyntaxNodeId original, int depth) throws Error {', '\tSyntaxNodeId absent = {index = 0};', '\tif (original.index == 0) return absent;', '\tif (original.index >= (index.generic_nodes + 1) || depth > 128 || index.bindings.program.arena.node_count > 262144) { index.fail(index.bindings.program.arena.header(original).span, "generic syntax resource limit"); return absent; }', '\tif (index.generic_node_map[plan.nodes + original.index] != 0) { SyntaxNodeId cached = {index = index.generic_node_map[plan.nodes + original.index]}; return cached; }', '\tvar header = index.bindings.program.arena.header(original);', '\tif (header.foreign_member.index != 0 || index.bindings.program.arena.list_count(header.foreign_channels) != 0) { index.fail(header.span, "DEFERRED: generic foreign metadata"); return absent; }', '\tvar result = absent;', '\tmatch (index.bindings.program.arena.kind(original)) {']
	check = ['// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception', '// Generated structural consumer. Never calls the instance builder.', 'bool generic_check_node(CheckedIndex index, GenericInstance plan, SyntaxNodeId original) {', '\tif (original.index <= 0 || original.index >= (index.generic_nodes + 1)) return false;', '\tSyntaxNodeId concrete = {index = index.generic_node_map[plan.nodes + original.index]};', '\tif (concrete.index <= index.generic_nodes || concrete.index >= len(index.uses)) return false;', '\tvar first = index.bindings.program.arena.header(original); var second = index.bindings.program.arena.header(concrete);', '\tif (first.kind_code != second.kind_code || first.span.source.index != second.span.source.index || first.span.start != second.span.start || first.span.end != second.span.end || first.depth != second.depth || first.module_internal != second.module_internal) return false;', '\tmatch (index.bindings.program.arena.kind(original)) {']
	for name in NAMES:
		record = model[name]
		stem = re.sub(r'(?<!^)(?=[A-Z])', '_', name.removesuffix('Syntax')).lower()
		copy += [f'\t\tcase SyntaxKind.{name}(): {{', f'\t\t\tvar data = index.bindings.program.arena.{stem}(original);']
		check += [f'\t\tcase SyntaxKind.{name}(): {{', f'\t\t\tvar first_data = index.bindings.program.arena.{stem}(original);', f'\t\t\tvar second_data = index.bindings.program.arena.{stem}(concrete);']
		for field, typ in record['fields'].items():
			if field in ('foreign_member', 'module_internal', 'foreign_channels'): continue
			f = 'f_'+field
			if field in ('type_parameters', 'where_clauses') and name in ('FunctionDeclarationSyntax', 'StructDeclarationSyntax', 'ClassDeclarationSyntax'):
				copy += [f'\t\t\tdata.{f}.index = 0;']
				check += [f'\t\t\tif (second_data.{f}.index != 0) return false;']
			elif name == 'ClassDeclarationSyntax' and field == 'members':
				copy += [f'\t\t\tdata.{f} = generic_class_members(index, plan, data.{f}, depth + 1);']
				check += [f'\t\t\tif (!generic_class_members_verified(index, plan, first_data.{f}, second_data.{f})) return false;']
			elif name == 'ClassDeclarationSyntax' and field == 'methods':
				copy += [f'\t\t\tdata.{f}.index = 0;']
				check += [f'\t\t\tif (index.bindings.program.arena.list_count(second_data.{f}) != 0) return false;']
			elif name == 'FunctionDeclarationSyntax' and field == 'parameters':
				copy += [f'\t\t\tdata.{f} = generic_copy_list(index, plan, data.{f}, syntax_kind_code(SyntaxKind.ParameterSyntax()), depth + 1);']
				check += [f'\t\t\tif (!generic_parameters_verified(index, plan, first_data.{f}, second_data.{f})) return false;']
			elif typ.rstrip('?') in model:
				copy += [f'\t\t\tdata.{f} = generic_copy_node(index, plan, data.{f}, depth + 1);']
				check += [f'\t\t\tif (!generic_check_child(index, plan, first_data.{f}, second_data.{f})) return false;']
			elif typ.startswith('GenericArray<') and typ[13:].rstrip('>?') in model:
				element = typ[13:].rstrip('>?')
				copy += [f'\t\t\tdata.{f} = generic_copy_list(index, plan, data.{f}, syntax_kind_code(SyntaxKind.{element}()), depth + 1);']
				check += [f'\t\t\tif (!generic_check_list(index, plan, first_data.{f}, second_data.{f})) return false;']
			elif typ.startswith('GenericArray<'):
				check += [f'\t\t\tif (first_data.{f}.index != second_data.{f}.index) return false;']
			elif typ == 'ConcurrencyPolicy?':
				for attr in ('present', 'kinds', 'admitted'): check += [f'\t\t\tif (first_data.{f}.{attr} != second_data.{f}.{attr}) return false;']
			elif typ.rstrip('?') in ('Token', 'Utf8Message'):
				check += [f'\t\t\tif (first_data.{f}.index != second_data.{f}.index) return false;']
			else:
				check += [f'\t\t\tif (first_data.{f} != second_data.{f}) return false;']
		copy += [f'\t\t\tif (!index.failed()) result = index.bindings.program.arena.add_{stem}(data, header.span, header.depth);', '\t\t}']
		check += ['\t\t}']
	copy += ['\t\telse: { index.fail(header.span, "DEFERRED: generic body syntax lacks a concrete specialization contract"); }', '\t}', '\tif (result.index != 0) {', '\t\tindex.generic_node_map[plan.nodes + original.index] = result.index;', '\t\tindex.bindings.program.arena.set_bool_module_internal(result, header.module_internal);', '\t}', '\treturn result;', '}', '', 'SyntaxListId generic_copy_list(CheckedIndex index, GenericInstance plan, SyntaxListId original, int element, int depth) throws Error {', '\tif (original.index == 0) return original;', '\tvar result = index.bindings.program.arena.new_list(element);', '\tint i = 0;', '\twhile (i < index.bindings.program.arena.list_count(original) && !index.failed()) {', '\t\tvar child = generic_copy_node(index, plan, index.bindings.program.arena.node_at(original, i), depth + 1);', '\t\tif (child.index == 0) break;', '\t\tindex.bindings.program.arena.append_node(result, child); i = i + 1;', '\t}', '\treturn result;', '}']
	check += ['\t\telse: { return false; }', '\t}', '\treturn true;', '}', '', 'bool generic_check_child(CheckedIndex index, GenericInstance plan, SyntaxNodeId original, SyntaxNodeId concrete) {', '\tif (original.index == 0) return concrete.index == 0;', '\treturn original.index > 0 && original.index < (index.generic_nodes + 1) && index.generic_node_map[plan.nodes + original.index] == concrete.index && concrete.index != 0;', '}', '', 'bool generic_check_list(CheckedIndex index, GenericInstance plan, SyntaxListId original, SyntaxListId concrete) {', '\tint count = index.bindings.program.arena.list_count(original);', '\tif (count != index.bindings.program.arena.list_count(concrete)) return false;', '\tint i = 0;', '\twhile (i < count) {', '\t\tif (!generic_check_child(index, plan, index.bindings.program.arena.node_at(original, i), index.bindings.program.arena.node_at(concrete, i))) return false;', '\t\ti = i + 1;', '\t}', '\treturn true;', '}']
	return {'generic-copy.astra': '\n'.join(copy)+'\n', 'generic-syntax-check.astra': '\n'.join(check)+'\n'}


if __name__ == '__main__':
	import sys
	for name, data in generate().items():
		path = Path(__file__).with_name(name)
		if '--check' in sys.argv:
			sys.path.insert(0, str(ROOT/'tools/format'))
			from lexical import scan
			assert [t[0] for t in scan(path.read_bytes())] == [t[0] for t in scan(data.encode())], name
		else:
			path.write_text(data)
